/* Customer 360: shared CMS/mobile relationship workspace. Financial feeds remain explicitly unconnected. */
let c360Tab='Overview',c360Focus='',c360Search='',c360Channel='Semua',c360AccountStatus='Semua',c360From='',c360To='';
const C360_TABS=['Overview','Cross-sell','Profil','Portofolio','Rekening & Transaksi','Kredit & Agunan','Interaksi & Keluhan','Task & Opportunity','Dokumen','Audit & Sumber'];
const C360_SCHEMAS={
 portfolio:{label:'Posisi produk',fields:[['product','Produk','product',true],['category','Kategori','pick',true,['Tabungan','Giro','Deposito','Kredit konsumtif','Kredit produktif']],['number','Referensi fasilitas','text'],['balance','Saldo dana','money'],['limit','Plafon','money'],['outstanding','Baki debet','money'],['creditType','Jenis kredit','text'],['collectibility','Kolektibilitas','pick',false,['Belum tersedia','1','2','3','4','5']],['maturity','Jatuh tempo','date'],['asOf','Posisi per tanggal','date',true],['note','Catatan sumber','area']]},
 accounts:{label:'Rekening',fields:[['product','Produk','product',true],['number','Nomor rekening','text',true],['category','Kategori','pick',true,['Tabungan','Giro','Deposito','Kredit']],['status','Status rekening','pick',true,['Aktif','Dormant','Tutup']],['balance','Saldo tercatat','money'],['currency','Mata uang','pick',true,['IDR']],['opened','Tanggal pembukaan','date'],['asOf','Posisi per tanggal','date',true],['transactionSummary','Ringkasan transaksi sumber','area']]},
 transactions:{label:'Transaksi',fields:[['accountId','Rekening terkait','account',true],['date','Tanggal transaksi','date',true],['direction','Arus','pick',true,['Masuk','Keluar']],['amount','Nominal','money',true],['channel','Channel','pick',true,['Cabang','ATM','Mobile Banking','Internet Banking','Transfer','Lainnya']],['description','Keterangan','area',true],['reference','Referensi transaksi','text']]},
 credits:{label:'Fasilitas kredit',fields:[['name','Nama fasilitas','text',true],['number','Referensi kredit','text'],['product','Produk','product',true],['creditType','Jenis kredit','text'],['limit','Plafon','money',true],['outstanding','Baki debet','money',true],['collectibility','Kolektibilitas','pick',true,['Belum tersedia','1','2','3','4','5']],['status','Status fasilitas','pick',true,['Aktif','Lunas','Ditutup']],['maturity','Jatuh tempo','date'],['asOf','Posisi per tanggal','date',true],['note','Informasi kredit','area']]},
 collaterals:{label:'Agunan',fields:[['type','Jenis agunan','pick',true,['Tanah & bangunan','Kendaraan','Deposito','Persediaan','Mesin','Lainnya']],['creditId','Fasilitas kredit','credit',false],['reference','Nomor referensi agunan','text'],['appraisal','Nilai taksasi','money',true],['appraisalDate','Tanggal taksasi','date'],['location','Lokasi agunan','area',true],['ownership','Pemilik / hubungan','text'],['documentReference','Referensi dokumen','text'],['note','Catatan agunan','area']]},
 interactions:{label:'Interaksi',fields:[['date','Tanggal interaksi','date',true],['channel','Channel','pick',true,['Marketing','Visit','Call','WhatsApp','Email','Complaint','Meeting','Follow-up']],['result','Hasil interaksi','text',true],['note','Catatan','area',true],['followUp','Rencana tindak lanjut','area'],['followUpDate','Target tindak lanjut','date']]},
 complaints:{label:'Keluhan',fields:[['date','Tanggal diterima','date',true],['channel','Channel','pick',true,['Cabang','Call Centre','WhatsApp','Email','Visit','Lainnya']],['subject','Judul keluhan','text',true],['note','Isi keluhan','area',true],['priority','Prioritas','pick',true,['Rendah','Normal','Tinggi']],['status','Status','pick',true,['Open','Dalam proses','Dieskalasikan','Resolved']],['assignee','PIC penanganan','text',true],['due','Target penyelesaian','date',true],['resolution','Penyelesaian / tindak lanjut','area']]},
 relationships:{label:'Hubungan customer',fields:[['customerId','Customer terkait','customer',true],['type','Jenis hubungan','pick',true,['Perusahaan tempat bekerja','Pemilik usaha','Pengurus','Keluarga','Referral','Grup usaha','Lainnya']],['note','Keterangan hubungan','area']]}
};
const c360Clone=x=>JSON.parse(JSON.stringify(x));
function c360Customer(id){const p=profile(id);return p&&p.relation==='Customer'&&mine(p)?p:null}
function c360Rows(p,key){const legacy=key==='credits'?[]:(p[key]||[]);const rows=p.customer360?.[key]??legacy;return Array.isArray(rows)?rows.map((r,i)=>({...r,id:r.id||'legacy-'+key+'-'+i})):[]}
function c360Editable(r){return !r.readOnly&&!r.locked&&!/core banking|los|terintegrasi/i.test(r.source||'')}
function c360Stamp(r){return '<small class="c360-source">'+E(r.source||'Pencatatan CRM')+' · '+E(r.asOf||r.updatedAt?.slice(0,10)||r.date||'Tanggal sumber belum tersedia')+(c360Editable(r)?'':' · Read only')+'</small>'}
function c360Choice(label,name,items,value='',required=false){return '<label>'+E(label)+'<select name="'+name+'" '+(required?'required':'')+'><option value="">Pilih…</option>'+items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return '<option value="'+E(v)+'" '+(v===value?'selected':'')+'>'+E(t)+'</option>'}).join('')+'</select></label>'}
function c360Input(spec,value,p){const [key,label,type,required,items]=spec;let choices=items;if(type==='product')choices=activeMaster('products').map(x=>x.name);if(type==='account')choices=c360Rows(p,'accounts').map(x=>[x.id,(x.product||'Rekening')+' · '+(x.number||x.id)]);if(type==='credit')choices=c360Rows(p,'credits').map(x=>[x.id,x.name||x.number||x.id]);if(type==='customer')choices=db.profiles.filter(x=>x.id!==p.id&&x.relation==='Customer'&&mine(x)).map(x=>[x.id,x.name]);if(choices){if(value&&!choices.some(x=>(Array.isArray(x)?x[0]:x)===value))choices=[[value,value],...choices];return c360Choice(label,key,choices,value,required)}if(type==='area')return area(label,key,value||'',required);return field(label,key,value??'',type==='money'?'number':type,required).replace('type="number"','type="number" min="0" step="0.01"')}
function c360Validate(p,key,value){const schema=C360_SCHEMAS[key];if(!schema)throw Error('Bagian tidak tersedia.');for(const [name,label,type,required]of schema.fields){if(required&&(value[name]==null||String(value[name]).trim()===''))throw Error(label+' wajib diisi.');if(type==='money'&&value[name]!==''&&value[name]!=null&&(!Number.isFinite(Number(value[name]))||Number(value[name])<0))throw Error(label+' harus angka nol atau lebih.');if(type==='date'&&value[name]&&!/^\d{4}-\d{2}-\d{2}$/.test(value[name]))throw Error(label+' tidak valid.');}
 if(key==='transactions'&&(!c360Rows(p,'accounts').some(x=>x.id===value.accountId)||Number(value.amount)<=0))throw Error('Pilih rekening terkait dan nominal lebih dari nol.');
 if(key==='accounts'&&c360Rows(p,'accounts').some(x=>x.id!==value.id&&x.number===value.number))throw Error('Nomor rekening sudah tercatat pada customer ini.');
 if(key==='collaterals'&&value.creditId&&!c360Rows(p,'credits').some(x=>x.id===value.creditId))throw Error('Fasilitas kredit tidak sesuai customer.');
 if(key==='relationships'&&!db.profiles.some(x=>x.id===value.customerId&&x.id!==p.id&&x.relation==='Customer'&&mine(x)))throw Error('Customer terkait tidak tersedia.');
 if(key==='complaints'&&value.status==='Resolved'&&!String(value.resolution||'').trim())throw Error('Isi hasil penyelesaian sebelum menutup keluhan.');
 return value;
}
function c360Save(id,key,value){const p=c360Customer(id);if(!p)throw Error('Customer tidak tersedia dalam akses Anda.');const rows=c360Rows(p,key),old=rows.find(x=>x.id===value.id);if(old&&!c360Editable(old))throw Error('Data sumber ini read only. Ajukan koreksi melalui pemilik data.');value=c360Validate(p,key,value);const row={...value,id:old?.id||uid('C360'),source:old?.source||'Pencatatan CRM',createdAt:old?.createdAt||now(),updatedAt:now(),actor:actor()};for(const [name,,type]of C360_SCHEMAS[key].fields)if(type==='money')row[name]=row[name]===''||row[name]==null?null:Number(row[name]);if(key==='complaints'){row.history=[...(old?.history||[]),{at:now(),by:actor(),status:row.status,note:row.resolution||row.note}];if(row.status==='Resolved')row.resolvedAt=now()}
 p.customer360={...(p.customer360||{}),[key]:old?rows.map(x=>x.id===row.id?row:x):[row,...rows]};p.updated=now();record('Customer 360 '+(old?'update ':'tambah ')+key,p.id,row.id);return row;
}
function c360Edit(id,key,rowId=''){const p=c360Customer(id);if(!p)return toast('Customer tidak tersedia.');const row=c360Rows(p,key).find(x=>x.id===rowId)||{};if(rowId&&!c360Editable(row))return toast('Data sumber read only.');const schema=C360_SCHEMAS[key];if(!schema)return;const defaults={date:today(),asOf:today(),assignee:actor(),priority:'Normal',status:key==='complaints'?'Open':'Aktif',currency:'IDR'};modal((rowId?'Edit ':'Tambah ')+schema.label,'<p class="hint">Pencatatan CRM manual. Tidak mengubah data Core Banking.</p>'+schema.fields.map(f=>c360Input(f,row[f[0]]??defaults[f[0]]??'',p)).join(''),f=>{c360Save(id,key,{...row,...f});});}
function c360ChangeTab(tab){if(!C360_TABS.includes(tab))return;c360Tab=tab;c360Search='';renderContent()}
function c360SearchRows(rows,search=c360Search){const q=search.toLowerCase();return rows.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q))}
function c360Number(value){return value==null||value===''?'Belum tersedia':rup(Number(value))}
function c360Metric(label,value,detail=''){return '<div class="c360-metric"><small>'+E(label)+'</small><strong>'+E(value)+'</strong>'+(detail?'<span>'+E(detail)+'</span>':'')+'</div>'}
function c360Facts(items){return '<div class="c360-facts">'+items.map(([label,value])=>'<div><small>'+E(label)+'</small><strong>'+E(value??'Belum tersedia')+'</strong></div>').join('')+'</div>'}
function c360SearchBox(){return '<label class="c360-search">Cari di bagian ini<input aria-label="Cari Customer 360" value="'+E(c360Search)+'" placeholder="Nama, referensi, catatan…" onchange="c360Search=this.value;renderContent()"></label>'}
function c360Section(title,body,action=''){return '<section class="panel c360-section"><div class="c360-section-head"><h2>'+E(title)+'</h2>'+action+'</div>'+body+'</section>'}
function c360RowActions(p,key,row){return c360Editable(row)?'<div class="actions">'+btn('Edit',"c360Edit('"+p.id+"','"+key+"','"+row.id+"')")+'</div>':''}
function c360Portfolio(p){const all=c360Rows(p,'portfolio'),rows=c360SearchRows(all);return c360Section('Customer Portfolio View','<p class="hint">Tabungan, Giro, Deposito, Kredit konsumtif dan Kredit produktif. Nilai mengikuti posisi per tanggal pada setiap sumber.</p>'+c360SearchBox()+'<div class="c360-cardgrid">'+rows.map(r=>'<article class="c360-card"><div class="recordtop">'+badge(r.category||r.creditType||'Produk Bank')+'</div><h3>'+E(r.product)+'</h3>'+c360Facts([['Referensi',r.number||'—'],['Saldo dana',c360Number(r.balance)],['Plafon',c360Number(r.limit)],['Baki debet',c360Number(r.outstanding)],['Jenis kredit',r.creditType||'—'],['Kolektibilitas',r.collectibility||'—'],['Jatuh tempo',r.maturity?fmt(r.maturity):'—']])+c360Stamp(r)+c360RowActions(p,'portfolio',r)+'</article>').join('')+(rows.length?'':empty('Belum ada posisi produk sesuai pencarian.'))+'</div>',btn('Tambah posisi produk',"c360Edit('"+p.id+"','portfolio')",true))}
function c360Accounts(p){const accounts=c360Rows(p,'accounts'),rows=c360SearchRows(accounts).filter(x=>c360AccountStatus==='Semua'||x.status===c360AccountStatus);const allTx=c360Rows(p,'transactions');const tx=c360SearchRows(allTx).filter(x=>(!c360From||x.date>=c360From)&&(!c360To||x.date<=c360To));const incoming=tx.filter(x=>x.direction==='Masuk').reduce((n,x)=>n+Number(x.amount||0),0),outgoing=tx.filter(x=>x.direction==='Keluar').reduce((n,x)=>n+Number(x.amount||0),0);
 return c360Section('Rekening', '<div class="rangechips">'+['Semua','Aktif','Dormant','Tutup'].map(s=>btn(s+' '+accounts.filter(a=>s==='Semua'||a.status===s).length,"c360AccountStatus='"+s+"';renderContent()",c360AccountStatus===s)).join('')+'</div>'+c360SearchBox()+'<div class="c360-cardgrid">'+rows.map(r=>'<article class="c360-card"><div class="recordtop">'+badge(r.status||'Status belum tersedia')+'</div><h3>'+E(r.product||'Rekening')+'</h3>'+c360Facts([['Nomor rekening',r.number||'—'],['Kategori',r.category||'—'],['Saldo tercatat',c360Number(r.balance)],['Mata uang',r.currency||'IDR'],['Ringkasan sumber',r.transactionSummary||'Belum tersedia']])+c360Stamp(r)+c360RowActions(p,'accounts',r)+'</article>').join('')+(rows.length?'':empty('Belum ada rekening sesuai filter.'))+'</div>',btn('Tambah rekening',"c360Edit('"+p.id+"','accounts')",true))+
 c360Section('Ringkasan dan histori transaksi','<div class="c360-filters"><label>Dari tanggal<input type="date" value="'+E(c360From)+'" onchange="c360From=this.value;renderContent()"></label><label>Sampai tanggal<input type="date" value="'+E(c360To)+'" onchange="c360To=this.value;renderContent()"></label>'+btn('Reset periode',"c360From='';c360To='';renderContent()")+'</div><div class="c360-metrics">'+c360Metric('Transaksi masuk',rup(incoming),tx.length+' record sesuai filter')+c360Metric('Transaksi keluar',rup(outgoing),'Total nominal record')+'</div><p class="hint">Ringkasan hanya menghitung record transaksi yang tersedia, bukan mutasi rekening lengkap. Saldo tercatat tidak dihitung ulang dari histori parsial.</p><div class="c360-timeline">'+tx.sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(r=>'<article><small>'+E(r.date)+' · '+E(r.channel)+'</small><h3>'+E(r.direction)+' · '+E(rup(r.amount))+'</h3><p>'+E(accounts.find(a=>a.id===r.accountId)?.number||r.accountId)+'</p><p>'+E(r.description)+'</p>'+c360Stamp(r)+c360RowActions(p,'transactions',r)+'</article>').join('')+(tx.length?'':empty('Belum ada transaksi sesuai periode.'))+'</div>',btn('Catat transaksi',"c360Edit('"+p.id+"','transactions')",true));
}
function c360Credit(p){const credits=c360Rows(p,'credits'),collaterals=c360Rows(p,'collaterals'),apps=db.applications.filter(a=>a.profile===p.id&&mine(a));return c360Section('Fasilitas dan posisi kredit','<div class="c360-cardgrid">'+c360SearchRows(credits).map(r=>'<article class="c360-card"><h3>'+E(r.name||r.product)+'</h3>'+c360Facts([['Referensi',r.number||'—'],['Jenis kredit',r.creditType||r.product],['Plafon',c360Number(r.limit)],['Baki debet',c360Number(r.outstanding)],['Kolektibilitas',r.collectibility||'Belum tersedia'],['Jatuh tempo',r.maturity?fmt(r.maturity):'—'],['Status',r.status||'Belum tersedia']])+c360Stamp(r)+c360RowActions(p,'credits',r)+'</article>').join('')+(credits.length?'':empty('Fasilitas kredit belum tercatat. Posisi produk lama tetap tersedia pada tab Portofolio.'))+'</div>',btn('Tambah fasilitas',"c360Edit('"+p.id+"','credits')",true))+c360Section('Agunan dan taksasi','<div class="c360-cardgrid">'+collaterals.map(r=>'<article class="c360-card"><h3>'+E(r.type)+'</h3>'+c360Facts([['Fasilitas',credits.find(c=>c.id===r.creditId)?.name||r.creditId||'Belum ditautkan'],['Nilai taksasi',c360Number(r.appraisal)],['Tanggal taksasi',r.appraisalDate||'Belum tersedia'],['Lokasi',r.location||'Belum tersedia'],['Pemilik',r.ownership||'Belum tersedia'],['Referensi dokumen',r.documentReference||'—']])+c360Stamp(r)+c360RowActions(p,'collaterals',r)+'</article>').join('')+(collaterals.length?'':empty('Belum ada informasi agunan.'))+'</div>',btn('Tambah agunan',"c360Edit('"+p.id+"','collaterals')",true))+c360Section('Histori pengajuan',apps.map(a=>'<article class="c360-card"><h3>'+E(a.number)+'</h3>'+c360Facts([['Produk',a.product],['Survey',a.survey],['Analisa',a.analysis],['Approval',a.approval],['Pencairan',a.disbursement]])+(a.opp?btn('Buka Opportunity',"go('Opportunity detail','"+a.opp+"')"):'')+'</article>').join('')||empty('Belum ada pengajuan terkait.'))}
function c360Timeline(p){const channels={'Telepon':'Call','Kunjungan':'Visit','Meeting':'Meeting'};return [...c360Rows(p,'interactions'),...db.activities.filter(a=>a.profile===p.id&&mine(a)).map(a=>({...a,id:'activity-'+a.id,activityId:a.id,date:(a.occurred||a.recorded||'').slice(0,10),channel:channels[a.type]||a.type,actor:a.owner,followUp:a.nextTask?'Task '+a.nextTask:'',source:'Task / CRM'})),...c360Rows(p,'complaints').map(x=>({...x,id:'complaint-'+x.id,complaintId:x.id,channel:'Complaint',result:x.status,note:x.subject+' · '+x.note,followUp:x.resolution,source:x.source||'Pencatatan CRM'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function c360Task(id,purpose){if(!c360Customer(id))return;newTask(id);const input=document.querySelector('#form [name="purpose"]');if(input)input.value=purpose||'Tindak lanjut Customer 360'}
function c360Interactions(p){const rows=c360SearchRows(c360Timeline(p)).filter(x=>c360Channel==='Semua'||x.channel===c360Channel),complaints=c360Rows(p,'complaints');return c360Section('Customer Interaction Timeline','<p class="hint">Marketing, Visit, Call, WhatsApp, Email, Complaint, Meeting dan Follow-up. Catatan channel manual ditandai; belum ada sinkronisasi otomatis WhatsApp, email atau call centre.</p><div class="c360-filters">'+c360Choice('Channel','c360Channel',['Semua','Marketing','Visit','Call','WhatsApp','Email','Complaint','Meeting','Follow-up'],c360Channel).replace('name="c360Channel"','name="c360Channel" onchange="c360Channel=this.value;renderContent()"')+c360SearchBox()+'</div><div class="c360-timeline">'+rows.map(r=>'<article><small>'+E(r.date||'Tanggal belum tersedia')+' · '+E(r.channel)+' · '+E(r.actor||r.owner||'—')+'</small><h3>'+E(r.result||'Interaksi')+'</h3><p>'+E(r.note||'')+'</p>'+(r.followUp?'<p><b>Tindak lanjut:</b> '+E(r.followUp)+' '+E(r.followUpDate||'')+'</p>':'')+c360Stamp(r)+'<div class="actions">'+(r.task?btn('Buka Task',"go('Aktivitas detail','"+r.task+"')"):!r.activityId&&!r.complaintId?btn('Edit',"c360Edit('"+p.id+"','interactions','"+r.id+"')"):'')+btn('Buat Task',"c360Task('"+p.id+"','Tindak lanjut interaksi')")+'</div></article>').join('')+(rows.length?'':empty('Belum ada interaksi sesuai filter.'))+'</div>',btn('Catat interaksi',"c360Edit('"+p.id+"','interactions')",true))+c360Section('Keluhan dan penyelesaian',complaints.map(r=>'<article class="c360-card"><div class="recordtop">'+badge(r.status||'Open')+badge(r.priority||'Normal')+'</div><h3>'+E(r.subject||'Keluhan')+'</h3><p>'+E(r.note)+'</p>'+c360Facts([['Diterima',r.date],['Channel',r.channel||'—'],['PIC',r.assignee||r.actor||'Belum ditetapkan'],['Target selesai',r.due||'Belum ditetapkan'],['Penyelesaian',r.resolution||'Belum ada']])+'<details><summary>Riwayat penanganan</summary>'+(r.history||[]).map(h=>'<p>'+E(h.at)+' · '+E(h.status)+' · '+E(h.by)+'<br>'+E(h.note)+'</p>').join('')+'</details>'+c360RowActions(p,'complaints',r)+btn('Buat Task penanganan',"c360Task('"+p.id+"','Penanganan keluhan customer')")+'</article>').join('')||empty('Belum ada keluhan.'),btn('Catat keluhan',"c360Edit('"+p.id+"','complaints')",true))}
function c360Signals(p){const data=p.customer360?.context||{},held=[...c360Rows(p,'portfolio'),...c360Rows(p,'accounts'),...c360Rows(p,'credits')].filter(x=>!['Tutup','Lunas','Ditutup'].includes(x.status)),products=activeMaster('products');const has=name=>held.some(x=>String(x.product||'').toLowerCase()===name.toLowerCase()||String(x.category||'').toLowerCase()===name.toLowerCase());const pending=db.opps.filter(o=>o.profile===p.id&&mine(o)&&o.outcome==='Aktif');return products.filter(x=>!has(x.name)).map(x=>{let reason='Produk belum tercatat pada portofolio. Konfirmasi kebutuhan dan kelengkapan data terlebih dahulu.',kind=/kredit|kur/i.test(x.name)?'Kredit':'Dana';if(kind==='Kredit'&&Number(data.workingCapitalNeed)>0)reason='Kebutuhan modal kerja tercatat '+rup(data.workingCapitalNeed)+'. Verifikasi tujuan, kemampuan dan kesesuaian produk.';if(/deposito/i.test(x.name)&&Number(data.surplusFunds)>0)reason='Dana belum digunakan tercatat '+rup(data.surplusFunds)+'. Konfirmasi tenor dan kebutuhan likuiditas.';return {product:x.name,kind,reason,existing:pending.find(o=>o.product===x.name)}})}
function c360CreateOpportunity(id,product){const p=c360Customer(id);if(!p)return;const signal=c360Signals(p).find(x=>x.product===product);if(!signal)return toast('Produk sudah dimiliki atau tidak aktif.');if(signal.existing)return go('Opportunity detail',signal.existing.id);newOpp(id);const form=document.querySelector('#form');if(!form)return;const set=(name,value)=>{const el=form.querySelector('[name="'+name+'"]');if(el)el.value=value};set('product',product);set('name','Cross-sell '+product+' — '+p.name);set('need',signal.reason);set('type','Expansion')}
function c360ContextEdit(id){const p=c360Customer(id);if(!p)return;const x=p.customer360?.context||{};modal('Konteks relationship',select('Jenis customer','customerType',['Perorangan','Badan usaha'],x.customerType||'Perorangan')+field('Segmen','segment',x.segment||'')+field('Jumlah karyawan','employees',x.employees??'','number')+field('Estimasi payroll bulanan (Rp)','payroll',x.payroll??'','number')+select('Payroll saat ini','payrollBank',['Belum diketahui','Bank lain','BPD Bali'],x.payrollBank||'Belum diketahui')+field('Kebutuhan modal kerja (Rp)','workingCapitalNeed',x.workingCapitalNeed??'','number')+field('Dana belum digunakan (Rp)','surplusFunds',x.surplusFunds??'','number')+select('Preferensi komunikasi','preferredChannel',['Belum ditentukan','Call','WhatsApp','Email','Visit','Meeting'],x.preferredChannel||'Belum ditentukan')+area('Catatan kebutuhan / relationship','note',x.note||''),f=>{for(const k of ['employees','payroll','workingCapitalNeed','surplusFunds']){if(f[k]!==''&&(!Number.isFinite(Number(f[k]))||Number(f[k])<0))throw Error('Angka relationship tidak valid.');f[k]=f[k]===''?null:Number(f[k])}p.customer360={...(p.customer360||{}),context:{...f,updatedAt:now(),actor:actor()}};p.updated=now();record('Customer 360 konteks relationship',p.id);})}
function c360Intelligence(p){const ctx=p.customer360?.context||{},signals=c360Signals(p),held=c360Rows(p,'portfolio').map(x=>x.product);const payrollPotential=Number(ctx.employees)>0&&ctx.payrollBank!=='BPD Bali';return c360Section('Relationship Intelligence','<p class="hint">Insight berbasis aturan dan data yang tercatat, bukan AI scoring, penilaian kelayakan kredit atau jaminan rekomendasi produk. Produk yang belum tercatat belum tentu benar-benar belum dimiliki.</p>'+c360Facts([['Produk tercatat',held.join(', ')||'Belum tersedia'],['Segmen',ctx.segment||'Belum tersedia'],['Potensi payroll',payrollPotential?ctx.employees+' karyawan · '+c360Number(ctx.payroll)+'/bulan':ctx.payrollBank==='BPD Bali'?'Payroll BPD Bali sudah tercatat':'Lengkapi data karyawan dan bank payroll'],['Kebutuhan modal',c360Number(ctx.workingCapitalNeed)],['Dana belum digunakan',c360Number(ctx.surplusFunds)],['Preferensi komunikasi',ctx.preferredChannel||'Belum ditentukan']])+(payrollPotential?'<article class="c360-card"><h3>Payroll Opportunity</h3><p>Konfirmasi kebutuhan payroll '+E(ctx.employees)+' karyawan dan layanan pendukung. Pilih produk yang sesuai dari master sebelum membuat Opportunity.</p>'+btn('Buat Task discovery payroll',"c360Task('"+p.id+"','Discovery payroll customer')")+'</article>':'')+'<div class="c360-cardgrid">'+signals.map((s,i)=>'<article class="c360-card">'+badge(s.kind)+'<h3>'+E(s.product)+'</h3><p>'+E(s.reason)+'</p>'+btn(s.existing?'Buka Opportunity aktif':'Buat Opportunity',"c360CreateOpportunity('"+p.id+"',"+E(JSON.stringify(s.product))+")",true)+'</article>').join('')+(signals.length?'':empty('Tidak ada gap produk terhadap master aktif.'))+'</div>',btn('Perbarui konteks',"c360ContextEdit('"+p.id+"')"))+c360Section('Jaringan dan referral',c360Rows(p,'relationships').map(r=>'<article class="c360-card"><h3>'+E(profile(r.customerId)?.name||'Customer di luar scope')+'</h3><p>'+E(r.type)+' · '+E(r.note||'')+'</p>'+(c360Customer(r.customerId)?btn('Buka Customer 360',"go('Nasabah detail','"+r.customerId+"')"):'')+c360RowActions(p,'relationships',r)+'</article>').join('')||empty('Belum ada hubungan customer yang dicatat.'),btn('Tambah hubungan',"c360Edit('"+p.id+"','relationships')"))}
function c360Profile(p){const lead=db.leads.find(x=>x.profile===p.id&&mine(x)),ctx=p.customer360?.context||{};return c360Section('Customer Profile',c360Facts([['Nama',p.name],['CIF',p.cif||'Belum tersedia'],['NIK',p.nik||'Belum tersedia'],['Fasilitas yang dinikmati',c360Rows(p,'portfolio').map(x=>x.product).join(', ')||p.facilities||'Belum tersedia'],['Alamat',p.address||'Belum tersedia'],['Alamat usaha / tempat bekerja',p.businessAddress||'Belum tersedia'],['Pekerjaan',p.occupation||'Belum tersedia'],['Kontak',p.contact||'—'],['Telepon',p.phone||'—'],['AO / RM',p.owner||'—'],['Jenis customer',ctx.customerType||'Belum tersedia'],['Segmen',ctx.segment||'Belum tersedia']])+'<div class="actions">'+btn('Ajukan koreksi identitas',"correction('profile','"+p.id+"')")+btn('Lengkapi konteks',"c360ContextEdit('"+p.id+"')")+'</div>')+c360Section('Asal dan hubungan konversi',c360Facts([['Asal customer',p.customerSource||p.dataSource||(lead?'Konversi Lead':'Input langsung')],['Lead asal',lead?.id||'Tidak ada'],['Sumber / referral',lead?[lead.source,lead.referral].filter(Boolean).join(' · '):'Tidak tersedia'],['Referensi konversi',p.reference||'—'],['Tanggal konversi',p.convertedAt?fmt(p.convertedAt):'—'],['Status customer',statusOfCustomer(p)],['Alasan status',p.statusReason||'—']])+(lead?btn('Lihat Lead asal',"go('Lead detail','"+lead.id+"')"):'')+btn(statusOfCustomer(p)==='Inactive'?'Aktifkan Customer':'Jadikan Inactive',"changeCustomerStatus('"+p.id+"')"))}
function c360Documents(p){const docs=c360Rows(p,'documents'),photos=db.tasks.filter(t=>t.profile===p.id&&mine(t)&&t.photo);return c360Section('Dokumen customer dan foto','<p class="hint">PDF, JPEG dan PNG hingga 3 MB per file. File hanya dapat diakses oleh pengguna yang memiliki akses customer ini.</p>'+docs.map(r=>'<article class="c360-card"><h3>'+E(r.name)+'</h3>'+c360Facts([['Kategori',r.category],['Terkait',r.creditId||r.collateralId||'Customer'],['Referensi',r.reference||'—'],['Berlaku sampai',r.expires||'Tidak ditentukan'],['Status',r.expires&&r.expires<today()?'Kedaluwarsa':'Tersedia'],['Diunggah',r.uploadedBy+' · '+(r.uploadedAt?fmt(r.uploadedAt):'—')]])+btn('Buka dokumen',"c360OpenDocument('"+p.id+"','"+r.id+"')")+'</article>').join('')+(docs.length?'':empty('Belum ada dokumen customer.'))+photos.map(t=>'<article class="c360-card"><h3>Foto kunjungan</h3><p>'+E(t.purpose)+'</p>'+btn('Buka Task dan foto',"go('Aktivitas detail','"+t.id+"')")+'</article>').join(''),btn('Upload dokumen / foto',"c360UploadForm('"+p.id+"')",true))}
function c360UploadForm(id){const p=c360Customer(id);if(!p)return;modal('Upload dokumen Customer 360','<label>File (maksimal 3 MB)<input id="c360File" type="file" accept="application/pdf,image/jpeg,image/png" required></label>'+field('Nama dokumen','name','','text',true)+select('Kategori','category',['Identitas','Kredit','Agunan','Foto usaha','Foto kunjungan','Lainnya'])+c360Choice('Fasilitas terkait','creditId',c360Rows(p,'credits').map(x=>[x.id,x.name||x.product]))+c360Choice('Agunan terkait','collateralId',c360Rows(p,'collaterals').map(x=>[x.id,x.type+' · '+(x.reference||x.id)]))+field('Referensi dokumen','reference')+field('Berlaku sampai','expires','','date'),f=>{const file=document.querySelector('#c360File')?.files?.[0];if(!file)throw Error('Pilih file.');if(!['application/pdf','image/jpeg','image/png'].includes(file.type)||file.size>3*1024*1024)throw Error('Gunakan PDF/JPEG/PNG maksimal 3 MB.');c360Upload(id,file,f);return false;})}
async function c360Upload(id,file,meta){const uploadUser=authUser?.id;const form=document.querySelector('#form');const submit=form?.querySelector('button.primary');if(submit)submit.disabled=true;try{if(journey)throw Error('Upload tidak tersedia pada simulasi.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('File tidak dapat dibaca.'));reader.readAsDataURL(file)});const result=await api('customer-documents',{profile:id,...meta,type:file.type,data});if(authUser?.id!==uploadUser)return;if(result.data)applyServer(result);document.querySelector('#modal').close();toast('Dokumen tersimpan');}catch(e){const error=document.querySelector('#formerror');if(error)error.textContent=e.message;else toast(e.message)}finally{if(submit)submit.disabled=false}}
async function c360OpenDocument(id,docId){const p=c360Customer(id);if(!p)return;try{const r=await fetch(API_ORIGIN+'/api/customer-document/'+encodeURIComponent(id)+'/'+encodeURIComponent(docId),{headers:{Authorization:'Bearer '+currentToken()}});if(!r.ok)throw Error('Dokumen tidak dapat dibuka.');const blob=await r.blob(),url=URL.createObjectURL(blob),doc=c360Rows(p,'documents').find(d=>d.id===docId);modal(E(doc?.name||'Dokumen'),'<a class="button" download="'+E(doc?.name||'dokumen')+'" href="'+url+'">Download file</a><p class="hint">Tutup untuk kembali ke Customer 360.</p>'+(blob.type.startsWith('image/')?'<img class="c360-document-image" alt="Dokumen customer" src="'+url+'">':'<iframe title="Preview dokumen PDF" class="c360-document-frame" src="'+url+'"></iframe>'),()=>{});document.querySelector('#form .actions:last-child')?.remove();document.querySelector('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}catch(e){toast(e.message)}}
function c360Overview(p){const accounts=c360Rows(p,'accounts'),credits=c360Rows(p,'credits'),portfolio=c360Rows(p,'portfolio');const cash=accounts.filter(a=>a.status==='Aktif'&&['Tabungan','Giro','Deposito'].includes(a.category)&&a.balance!=null);const portfolioCash=portfolio.filter(a=>!a.category?.toLowerCase().includes('kredit')&&a.balance!=null);const source=cash.length?cash:portfolioCash;const debt=credits.length?credits:portfolio.filter(a=>a.outstanding!=null);const complaints=c360Rows(p,'complaints').filter(x=>x.status!=='Resolved');const ts=db.tasks.filter(t=>t.profile===p.id&&mine(t)&&isOpen(t));const os=db.opps.filter(o=>o.profile===p.id&&mine(o)&&o.outcome==='Aktif');const identity=[p.name,p.cif,p.nik,p.address,p.businessAddress,p.occupation,p.phone].filter(Boolean).length;return '<div class="c360-metrics">'+c360Metric('Saldo dana tercatat',source.length?rup(source.reduce((n,a)=>n+Number(a.balance||0),0)):'Belum tersedia','IDR · posisi sumber, bukan saldo real time')+c360Metric('Baki debet tercatat',debt.length?rup(debt.reduce((n,a)=>n+Number(a.outstanding||0),0)):'Belum tersedia','IDR · fasilitas tercatat')+c360Metric('Opportunity aktif',os.length,'Peluang terkait customer')+c360Metric('Task terbuka',ts.length,complaints.length+' keluhan belum selesai')+'</div>'+c360Section('Ringkasan relationship',c360Facts([['Kelengkapan identitas',identity+' / 7 field utama'],['AO / RM',p.owner],['Produk tercatat',portfolio.length],['Rekening dormant',accounts.filter(a=>a.status==='Dormant').length],['Fasilitas jatuh tempo 30 hari',debt.filter(a=>a.maturity&&a.maturity>=today()&&Date.parse(a.maturity)-Date.parse(today())<=30*86400000).length],['Terakhir interaksi',c360Timeline(p)[0]?.date||'Belum tersedia']])+'<p class="hint">Core Banking, LOS dan channel Bank belum terhubung. Data CRM manual dan data contoh diberi sumber serta tanggal posisi; angka kosong tidak dianggap nol.</p>')+c360Section('Prioritas tindak lanjut',complaints.length?'<p>'+complaints.length+' keluhan memerlukan penanganan.</p>'+btn('Buka keluhan',"c360ChangeTab('Interaksi & Keluhan')"):empty('Tidak ada keluhan terbuka yang tercatat.'))+c360Section('Interaksi terbaru',c360Timeline(p).slice(0,3).map(x=>'<article class="c360-card"><small>'+E(x.date)+' · '+E(x.channel)+'</small><p>'+E(x.result||x.note||'Interaksi')+'</p></article>').join('')||empty('Belum ada interaksi.'))}
function c360Related(p){const tasks=db.tasks.filter(t=>t.profile===p.id&&mine(t)),opps=db.opps.filter(o=>o.profile===p.id&&mine(o));return c360Section('Task dan follow-up',tasks.map(taskCard).join('')||empty('Belum ada Task.'),btn('Buat Task',"newTask('"+p.id+"')",true))+c360Section('Opportunity terkait',opps.map(oppCard).join('')||empty('Belum ada Opportunity.'),btn('Buat Opportunity',"newOpp('"+p.id+"')",true))}
function c360Sources(p){const rows=['portfolio','accounts','transactions','credits','collaterals','interactions','complaints','relationships','documents'].flatMap(key=>c360Rows(p,key).map(r=>({...r,section:key})));return c360Section('Sumber dan kesegaran data','<p>Core Banking: <strong>Belum terhubung</strong> · LOS: <strong>Belum terhubung</strong> · WhatsApp / email / call centre: <strong>Belum terhubung</strong></p><p class="hint">Read only dipakai untuk record yang berasal dari sistem sumber. Koreksi identitas mengikuti menu Persetujuan. Tidak ada klaim sinkronisasi otomatis.</p><div class="c360-timeline">'+rows.map(r=>'<article><strong>'+E(r.section)+' · '+E(r.product||r.name||r.subject||r.id)+'</strong>'+c360Stamp(r)+'</article>').join('')+(rows.length?'':empty('Belum ada data sumber.'))+'</div>')+c360Section('Audit perubahan customer',history(p.id))}
function c360Detail(p){if(!c360Customer(p.id))return empty('Customer tidak tersedia dalam akses Anda.');if(c360Focus!==p.id){c360Focus=p.id;c360Tab='Overview';c360Search='';c360Channel='Semua';c360AccountStatus='Semua';c360From='';c360To=''}const sections={'Overview':c360Overview,'Profil':c360Profile,'Portofolio':c360Portfolio,'Rekening & Transaksi':c360Accounts,'Kredit & Agunan':c360Credit,'Interaksi & Keluhan':c360Interactions,'Cross-sell':c360Intelligence,'Task & Opportunity':c360Related,'Dokumen':c360Documents,'Audit & Sumber':c360Sources};return '<div class="c360"><section class="c360-hero"><small>CUSTOMER 360</small><div class="c360-hero-title"><div><h1>'+E(p.name)+'</h1><p>CIF '+E(p.cif||'belum tersedia')+' · '+E(p.owner||'AO belum ditentukan')+'</p></div>'+badge(statusOfCustomer(p))+'</div><p>'+E(p.occupation||'Single customer view dan relationship intelligence')+'</p><div class="actions">'+btn('Cross-sell',"c360ChangeTab('Cross-sell')",true)+btn('Buat Task',"newTask('"+p.id+"')",true)+btn('Buat Opportunity',"newOpp('"+p.id+"')")+btn('Daftar customer',"go('Nasabah')")+'</div></section><nav class="c360-tabs" aria-label="Bagian Customer 360">'+C360_TABS.map(t=>'<button aria-pressed="'+(c360Tab===t)+'" class="'+(c360Tab===t?'active':'')+'" onclick="c360ChangeTab('+E(JSON.stringify(t))+')">'+E(t)+'</button>').join('')+'</nav>'+(sections[c360Tab]||c360Overview)(p)+'</div>'}
const c360PreviousDetail=nasabahRecordDetail;
nasabahRecordDetail=function(p){return p.relation==='Customer'?c360Detail(p):c360PreviousDetail(p)};
function c360Rename(){for(const root of [document.querySelector('#nav'),document.querySelector('#app'),document.querySelector('#modal'),document.querySelector('#title'),document.querySelector('#guidanceTour')]){if(!root)continue;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(['SCRIPT','STYLE','INPUT','TEXTAREA'].includes(node.parentElement?.tagName))continue;const text=node.nodeValue,next=text.trim()==='Nasabah'?text.replace('Nasabah','Customer 360'):text.replace(/Nasabah/g,'Customer').replace(/nasabah/g,'customer');if(text!==next)node.nodeValue=next;}for(const el of root.querySelectorAll('[placeholder],[aria-label]'))for(const attr of ['placeholder','aria-label']){const value=el.getAttribute(attr);if(value&&/nasabah/i.test(value))el.setAttribute(attr,value.replace(/Nasabah/g,'Customer').replace(/nasabah/g,'customer'));}}}
const c360PreviousRender=render;
render=function(){c360PreviousRender();c360Rename()};
const c360PreviousContent=renderContent;
renderContent=function(){c360PreviousContent();if(view==='Nasabah'){const title=document.querySelector('#app .intro h1');if(title)title.textContent='Customer 360';const subtitle=document.querySelector('#app .intro p');if(subtitle)subtitle.textContent='Single customer view, portofolio, interaksi dan peluang pengembangan hubungan.';}if(['Nasabah','Nasabah detail'].includes(view))document.querySelector('#title').textContent='Customer 360';c360Rename()};
const c360PreviousModal=modal;
modal=function(title,html,handler){c360PreviousModal(title,html,handler);c360Rename()};
if(typeof MutationObserver!=='undefined'){const root=document.querySelector('#app');if(root)new MutationObserver(()=>c360Rename()).observe(root,{subtree:true,childList:true});}
if(typeof authUser!=='undefined'&&authUser)render();

const c360PreviousGetList=getList;
getList=function(name=view){if(name!=='Nasabah')return c360PreviousGetList(name);const query=listQuery;listQuery='';let rows;try{rows=c360PreviousGetList(name)}finally{listQuery=query}const q=String(query||'').toLowerCase();return rows.filter(p=>!q||[p.name,p.contact,p.phone,p.cif,p.nik,p.id].some(x=>String(x||'').toLowerCase().includes(q)))};
